entries[41111] = { ["name"] = "Dehnbares Innenfutter", ["text"] = "Benutzen: Bringt an einem Umhang dauerhaft ein dehnbares Innenfutter an, das es Euch gestattet, Euren Umhang 30 Sek. lang als Fallschirm zu nutzen.\n\nDer Umhang kann nur einmal pro Minute genutzt werden und benötigt Ingenieurskunst von Nordend auf mindestens Stufe 1.\nBenötigt Ingenieurskunst von Nordend (1)\nVerkaufspreis:" }
