entries[41118] = { ["name"] = "Nitrobooster", ["text"] = "Benutzen: Bringt dauerhaft einen Nitrobooster an Eurem Gürtel an. Dadurch wird Eure Laufgeschwindigkeit für einige Sekunden erhöht. (2 Min. Abklingzeit)\n\nNitrobooster teilen sich die Abklingzeit mit Tränken.\nBenötigt Ingenieurskunst von Nordend (1)\nVerkaufspreis:" }
entries[41119] = { ["name"] = "Saronitbombe", ["text"] = "Benutzen: Verursacht bei Zielen in einem Radius von 10 Metern 50 Feuerschaden. Die Explosion ist stark genug, um moderaten Belagerungsschaden zu verursachen. (1 Min Abklingzeit)\nBenötigt Ingenieurskunst der Scherbenwelt (50)\nVerkaufspreis:" }
entries[41120] = { ["name"] = "Pläne: Verstärkte Kobaltbeinplatten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung verstärkter Kobaltbeinplatten.\nBenötigt Schmiedekunst von Nordend (1)\nVerkaufspreis:\nVerstärkte Kobaltbeinplatten\nWird beim Anlegen gebunden\nBeine Platte\n13 Rüstung\n+4 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\n+ 5 Vielseitigkeit\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Kobaltbarren (8), Kristallisiertes Wasser (2)\nOptionale Reagenzien: [] (#49)" }
entries[41121] = { ["name"] = "Gnomischer Blitzgenerator", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nBenutzen: Erzeugt einen Blitzstrahl, der einen Feind für 87 Naturschaden trifft. Das ganze Gehäuse des Geräts ist aus Metall... (1 Min Abklingzeit)\nBenötigt Ingenieurskunst von Nordend (50)\n\"Garantiert sicher!\"\nVerkaufspreis:" }
