entries[41507] = { ["name"] = "Riesige Zephyriumladung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Sprengt das Schloss von Gymers Käfig.\n\"Größe XXXL\"" }
entries[41508] = { ["name"] = "Feuerstuhl", ["text"] = "Reittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Wenn sie auch schwer zu bauen und zu pflegen sind, machen diese Feuerstühle den Aufwand durch schiere Großartigkeit wett.\"\nBeruf:\nIngenieurskunst" }
entries[41509] = { ["name"] = "Froststoffnetz", ["text"] = "Benutzen: Fängt ein bis zu 35 Meter entferntes Ziel 3 Sek. lang in einem Netz ein. (1 Min Abklingzeit)\nBenötigt Schneiderei von Nordend (1)\nVerkaufspreis:" }
